for (const auto& ring : polygon_coords) {
    std::vector<Triangulation::Vertex_handle> vertices;
    for (const auto& coord : ring) {
        Kernel::Point_2 p(coord[0], coord[1]);
        Triangulation::Vertex_handle v = triangulation.insert(p, walk_start);
        vertices.push_back(v);
        walk_start = triangulation.locate(p);
    }

    for (size_t i = 0; i < vertices.size(); ++i) {
        Triangulation::Vertex_handle v1 = vertices[i];
        Triangulation::Vertex_handle v2 = vertices[(i + 1) % vertices.size()];
        if (v1 != v2) {
            triangulation.odd_even_insert_constraint(v1, v2);
        }
    }
}

